import{_ as a,o as t,c as i,a2 as r}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Shared Familiarity and training","description":"","frontmatter":{},"headers":[],"relativePath":"en/game-design/characters/familiarity.md","filePath":"en/game-design/characters/familiarity.md"}'),n={name:"en/game-design/characters/familiarity.md"};function o(s,e,d,l,c,p){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="shared-familiarity-and-training" tabindex="-1">Shared Familiarity and training <a class="header-anchor" href="#shared-familiarity-and-training" aria-label="Permalink to &quot;Shared Familiarity and training&quot;">​</a></h1><p><strong>Design status: Proposed.</strong> Numeric examples are prototype hypotheses, not final balance. <strong>Implementation/availability:</strong> not established for these mechanics. <strong>Verification:</strong> documentation review, no playable prototype. <strong>Reviewed:</strong> 2026-10-09, Batch 05.</p><p><a href="/Syrolands-Public/en/guide/characters/familiarity.html">Player guide</a> · <a href="/Syrolands-Public/en/game-design/combat/overview.html">Combat foundations</a> · <a href="/Syrolands-Public/en/game-design/combat/variable-registry.html">Combat Variable Registry</a></p><h2 id="one-fluency-vocabulary" tabindex="-1">One fluency vocabulary <a class="header-anchor" href="#one-fluency-vocabulary" aria-label="Permalink to &quot;One fluency vocabulary&quot;">​</a></h2><p><strong>Skill → Technique → Familiarity → Prepared Repertoire → Player Execution</strong> separates general capability, permanent learning, practiced execution, ready options and applied timing. For spells, Active Memory is the related preparation system, not a claim that martial slots and spell memory share capacity formulas.</p><p>Batch 05 proposes three shared states for SAs and spell-pattern Familiarity: <strong>Learned, Practiced, Mastered</strong>. This supersedes Batch 04&#39;s illustrative “recently learned / familiar / highly familiar / deeply internalized” labels as the current proposed vocabulary; it does not promote a scale to Accepted balance. Wider discipline/affinity Mastery and core skill mastery at 100 remain separate concepts.</p><table tabindex="0"><thead><tr><th>State</th><th>Proposed execution quality</th><th>What remains</th></tr></thead><tbody><tr><td>Learned</td><td>Higher stamina cost, worse recovery, lower consistency/accuracy, more obvious telegraph, narrower response windows where relevant</td><td>Technique is known; validity/preparation conditions still apply</td></tr><tr><td>Practiced</td><td>Standard/baseline execution</td><td>Knowledge remains permanent</td></tr><tr><td>Mastered</td><td>Somewhat better stamina/recovery efficiency, consistency, forgiving timing and refined telegraph/control</td><td>No huge raw damage bonus or universal success</td></tr></tbody></table><p>Effects are action-specific candidates, not mandatory penalties on every spell. Spell resource/reference/Concentration effects remain with magic; Familiarity consumes no additional skillcap. Acquisition is permanent: fluency may move <strong>Mastered → Practiced → Learned</strong>, never back to Unknown through decay. Basic access does not randomly disappear because practice is low. Forgetting/respec by choice is outside this decay proposal.</p><h2 id="maintenance-without-absence-punishment" tabindex="-1">Maintenance without absence punishment <a class="header-anchor" href="#maintenance-without-absence-punishment" aria-label="Permalink to &quot;Maintenance without absence punishment&quot;">​</a></h2><p>Use a rolling <strong>active-days</strong> window rather than pure real-world calendar decay. Absence should not punish the player. Qualifying world use maintains fluency; dedicated facilities can do so with fewer repetitions. What counts as an active day or a qualifying use is Unresolved and must prevent trivial spam/macros.</p><table tabindex="0"><thead><tr><th>Illustrative maintenance prototype only</th><th>World-use candidate</th><th>Dedicated-training alternative</th></tr></thead><tbody><tr><td>Mastered</td><td>About 20 qualifying uses across about 7 active days</td><td>About 5 repetitions</td></tr><tr><td>Practiced</td><td>About 8–10 qualifying uses; precise window unresolved</td><td>About 2–3 repetitions</td></tr><tr><td>Learned</td><td>No maintenance to retain knowledge</td><td>Never decays away</td></tr></tbody></table><p>These Batch 05 illustrative counts are not runtime settings or final requirements. The scoped <a href="/Syrolands-Public/en/game-design/combat/numeric-prototype.html#maintenance-test">Batch 06 test</a> now chooses 9/3 for Practiced and a seven-active-day window for both tiers; outside that test, the broader questions remain open. Mastered&#39;s example window must not silently become the final Practiced window. Gain into higher tiers, activity definition, evaluation boundaries, partial progress, exploit controls and decay rate require tests. Prepared techniques might decay more slowly than unprepared ones; no rule is selected.</p><h2 id="training-facilities-and-crafts" tabindex="-1">Training facilities and crafts <a class="header-anchor" href="#training-facilities-and-crafts" aria-label="Permalink to &quot;Training facilities and crafts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Proposed facility</th><th>Candidate crafted support</th></tr></thead><tbody><tr><td>City martial gym/training hall</td><td>Training Dummy, Reinforced Combat Dummy, Articulated Limb Dummy</td></tr><tr><td>Mage academy/spell practice circle</td><td>Magical practice focus</td></tr><tr><td>House/guild training room</td><td>Appropriate practice objects and mechanisms</td></tr><tr><td>Ranged training area</td><td>Moving Target, archery range mechanisms</td></tr></tbody></table><p>Carpentry, Tinkering and Inscription may contribute; this does not allocate final recipes or create new skills. Facilities efficiently maintain familiarity and reduce chores. They should not be the optimal core-skill gain loop or trivialize discovery/mastery. Ownership/access, challenge validity, safety and automation controls remain open.</p><h2 id="preparation-and-int" tabindex="-1">Preparation and INT <a class="header-anchor" href="#preparation-and-int" aria-label="Permalink to &quot;Preparation and INT&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/combat/actions.html#learning-familiarity-and-prepared-options">Prepared Combat Repertoire</a> proposes five SA slots only as an initial UX test. INT is not a fixed prerequisite or warrior tax. Spell <a href="/Syrolands-Public/en/game-design/magic/memory-and-familiarity.html">Active Memory</a> retains its own proposed cognitive complexity model; do not transfer five martial slots into magic.</p><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><p>Outside the scoped <a href="/Syrolands-Public/en/game-design/combat/numeric-prototype.html#maintenance-test">Batch 06 retention test</a>, tier entry/maintenance/decay thresholds, qualifying use, active-day definition, training equivalence, prepared decay advantage, per-action effects, UI feedback, macro resistance, accessibility and how spell fizzle/Concentration interact with fluency. This changes no skill gain, save data or learned techniques in runtime.</p><h2 id="batch-06-numeric-test-scope" tabindex="-1">Batch 06 numeric test scope <a class="header-anchor" href="#batch-06-numeric-test-scope" aria-label="Permalink to &quot;Batch 06 numeric test scope&quot;">​</a></h2><p>The <a href="/Syrolands-Public/en/game-design/combat/numeric-prototype.html">three-weapon profile</a> assigns Experimental test values for Longsword, Spear and War Hammer. Its phase, resource, cadence, Flow, martial Familiarity and preparation rules apply only to that future test. Earlier examples remain historical alternatives outside this profile; no final balance, gameplay implementation or spell-number assignment follows.</p>',21)])])}const u=a(n,[["render",o]]);export{m as __pageData,u as default};
